   622→        prover.prove_satisfiability(&spec_a);
   623→        prover.prove_consistency(&spec_a, &spec_b);
   624→        prover.prove_satisfiability(&spec_c);
   625→
   626→        let proofs_for_a = prover.get_proofs_for_spec(spec_a.spec_id.as_str());
   627→        assert_eq!(proofs_for_a.len(), 2); // satisfiability + consistency
   628→
   629→        let proofs_for_c = prover.get_proofs_for_spec(spec_c.spec_id.as_str());
   630→        assert_eq!(proofs_for_c.len(), 1); // only satisfiability
   631→    }
   632→}
