   254→    #[cfg(feature = "z3-solver")]
   255→    fn encode_constraint<'ctx>(
   256→        &'ctx self,
   257→        description: &str,
   258→        var_map: &mut HashMap<String, Int<'ctx>>,
   259→    ) -> Option<Bool<'ctx>> {
   260→        let desc_lower = description.to_lowercase();
   261→
   262→        // Extract variable name (heuristic: first word before "must")
   263→        let var_name = self.extract_variable_name(&desc_lower).unwrap_or_else(|| "x".to_string());
   264→
   265→        // Get or create variable
   266→        let var = if let Some(existing) = var_map.get(&var_name) {
   267→            existing.clone()
   268→        } else {
   269→            let new_var = Int::new_const(&self.context, var_name.as_str());
   270→            var_map.insert(var_name.clone(), new_var.clone());
   271→            new_var
   272→        };
   273→
   274→        // Pattern matching for constraint types
   275→        if let Some(min) = self.extract_minimum(&desc_lower) {
   276→            // "at least N", "minimum N", ">= N"
   277→            let n = Int::from_i64(&self.context, min);
   278→            return Some(var.ge(&n));
   279→        }
   280→
   281→        if let Some(max) = self.extract_maximum(&desc_lower) {
   282→            // "at most N", "maximum N", "<= N"
   283→            let n = Int::from_i64(&self.context, max);
   284→            return Some(var.le(&n));
   285→        }
   286→
   287→        if let Some(exact) = self.extract_exact(&desc_lower) {
   288→            // "exactly N", "must be N"
   289→            let n = Int::from_i64(&self.context, exact);
   290→            return Some(var._eq(&n));
   291→        }
   292→
   293→        if let Some((min, max)) = self.extract_range(&desc_lower) {
   294→            // "between X and Y"
   295→            let min_val = Int::from_i64(&self.context, min);
   296→            let max_val = Int::from_i64(&self.context, max);
   297→            let ge = var.ge(&min_val);
   298→            let le = var.le(&max_val);
   299→            return Some(Bool::and(&self.context, &[&ge, &le]));
   300→        }
   301→
   302→        // Unable to encode this constraint
   303→        None
   304→    }
   305→
   306→    #[cfg(feature = "z3-solver")]
   307→    fn extract_variable_name(&self, desc: &str) -> Option<String> {
   308→        // Extract variable name from patterns like "password must be..."
   309→        let words: Vec<&str> = desc.split_whitespace().collect();
   310→        if let Some(pos) = words.iter().position(|&w| w == "must" || w == "should") {
   311→            if pos > 0 {
   312→                return Some(words[pos - 1].to_string());
   313→            }
   314→        }
   315→        None
   316→    }
   317→
   318→    fn extract_minimum(&self, desc: &str) -> Option<i64> {
   319→        if let Some(pos) = desc.find("at least") {
   320→            return self.extract_number(&desc[pos..]);
   321→        }
   322→        if let Some(pos) = desc.find("minimum") {
   323→            return self.extract_number(&desc[pos..]);
   324→        }
   325→        if let Some(pos) = desc.find(">=") {
   326→            return self.extract_number(&desc[pos..]);
   327→        }
   328→        None
   329→    }
   330→
   331→    fn extract_maximum(&self, desc: &str) -> Option<i64> {
   332→        if let Some(pos) = desc.find("at most") {
   333→            return self.extract_number(&desc[pos..]);
   334→        }
   335→        if let Some(pos) = desc.find("maximum") {
   336→            return self.extract_number(&desc[pos..]);
   337→        }
   338→        if let Some(pos) = desc.find("<=") {
   339→            return self.extract_number(&desc[pos..]);
   340→        }
   341→        None
   342→    }
   343→
   344→    fn extract_exact(&self, desc: &str) -> Option<i64> {
   345→        if let Some(pos) = desc.find("exactly") {
   346→            return self.extract_number(&desc[pos..]);
   347→        }
   348→        if desc.contains("must be") && !desc.contains("at least") && !desc.contains("at most") {
   349→            return self.extract_number(desc);
   350→        }
   351→        None
   352→    }
   353→
   354→    fn extract_range(&self, desc: &str) -> Option<(i64, i64)> {
   355→        if let Some(pos) = desc.find("between") {
   356→            let rest = &desc[pos..];
   357→            let numbers: Vec<i64> = rest.split_whitespace()
   358→                .filter_map(|w| w.trim_matches(|c: char| !c.is_numeric()).parse::<i64>().ok())
   359→                .collect();
   360→            if numbers.len() >= 2 {
   361→                return Some((numbers[0], numbers[1]));
   362→            }
   363→        }
   364→        None
   365→    }
   366→
   367→    fn extract_number(&self, s: &str) -> Option<i64> {
   368→        for word in s.split_whitespace() {
   369→            if let Ok(n) = word.trim_matches(|c: char| !c.is_numeric()).parse::<i64>() {
   370→                return Some(n);
   371→            }
   372→        }
   373→        None
   374→    }
   375→}
