   215→/// Transform function identifier with enforced "f_{source}_to_{target}" format
   216→///
   217→/// Valid formats:
   218→/// - "f_U1_to_U0" (inverse mapping)
   219→/// - "f_U1_to_U2" (forward/parallel mapping)
   220→#[derive(Debug, Clone, PartialEq, Eq, Hash)]
   221→pub struct TransformId(String);
   222→
   223→impl TransformId {
   224→    /// Create an inverse mapping ID: f_{source}_to_U0
   225→    pub fn inverse(source: &UniverseId) -> Self {
   226→        Self(format!("f_{}_to_U0", source.as_str()))
   227→    }
   228→
   229→    /// Create a forward/parallel mapping ID: f_{source}_to_{target}
   230→    pub fn forward(source: &UniverseId, target: &UniverseId) -> Self {
   231→        Self(format!("f_{}_to_{}", source.as_str(), target.as_str()))
   232→    }
   233→
   234→    /// Parse from string (validates format)
   235→    pub fn parse(s: &str) -> Result<Self, IdError> {
   236→        if !s.starts_with("f_") {
   237→            return Err(IdError::InvalidFormat(
   238→                format!("Transform ID must start with 'f_', got: {}", s),
   239→            ));
   240→        }
   241→
   242→        if !s.contains("_to_") {
   243→            return Err(IdError::InvalidFormat(
   244→                format!("Transform ID must contain '_to_', got: {}", s),
   245→            ));
   246→        }
   247→
   248→        // Extract source and target
   249→        let parts: Vec<&str> = s.split("_to_").collect();
   250→        if parts.len() != 2 {
   251→            return Err(IdError::InvalidFormat(
   252→                format!("Invalid transform ID format: {}", s),
   253→            ));
   254→        }
   255→
   256→        let source_part = parts[0].strip_prefix("f_").ok_or_else(|| {
   257→            IdError::InvalidFormat(format!("Invalid source in: {}", s))
   258→        })?;
   259→
   260→        // Validate source and target as UniverseIds
   261→        UniverseId::parse(source_part)?;
   262→        UniverseId::parse(parts[1])?;
   263→
   264→        Ok(Self(s.to_string()))
   265→    }
   266→
   267→    /// Get the source universe ID
   268→    pub fn source(&self) -> UniverseId {
   269→        let parts: Vec<&str> = self.0.split("_to_").collect();
   270→        let source_str = parts[0].strip_prefix("f_").unwrap();
   271→        UniverseId::parse(source_str).unwrap()
   272→    }
   273→
   274→    /// Get the target universe ID
   275→    pub fn target(&self) -> UniverseId {
   276→        let parts: Vec<&str> = self.0.split("_to_").collect();
   277→        UniverseId::parse(parts[1]).unwrap()
   278→    }
   279→
   280→    /// Get the string representation
   281→    pub fn as_str(&self) -> &str {
   282→        &self.0
   283→    }
   284→}
   285→
   286→impl fmt::Display for TransformId {
   287→    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
   288→        write!(f, "{}", self.0)
   289→    }
   290→}
   291→
   292→impl Serialize for TransformId {
   293→    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
   294→    where
   295→        S: Serializer,
   296→    {
   297→        serializer.serialize_str(&self.0)
   298→    }
   299→}
   300→
   301→impl<'de> Deserialize<'de> for TransformId {
   302→    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
   303→    where
   304→        D: Deserializer<'de>,
   305→    {
   306→        let s = String::deserialize(deserializer)?;
   307→        TransformId::parse(&s).map_err(serde::de::Error::custom)
   308→    }
   309→}
