     9→/// Well-known metadata keys
    10→///
    11→/// This enum prevents typos and provides type-safe metadata access.
    12→/// Custom keys can still be used via MetadataKey::Custom(String).
    13→#[derive(Debug, Clone, PartialEq, Eq, Hash)]
    14→pub enum MetadataKey {
    15→    /// Universe identifier (e.g., "U1", "U2")
    16→    Universe,
    17→    /// Source file path
    18→    SourceFile,
    19→    /// RPC method name
    20→    RpcName,
    21→    /// Extractor that produced this specification
    22→    Extractor,
    23→    /// Whether this was inferred (vs. manually written)
    24→    Inferred,
    25→    /// Variable name in code
    26→    Variable,
    27→    /// Implementation code snippet
    28→    ImplCode,
    29→    /// Test code snippet
    30→    TestCode,
    31→    /// Pattern that was matched
    32→    Pattern,
    33→    /// Specific value
    34→    Value,
    35→    /// Minimum constraint value
    36→    Min,
    37→    /// Maximum constraint value
    38→    Max,
    39→    /// Source of the specification
    40→    Source,
    41→    /// Custom key (for extensibility)
    42→    Custom(String),
    43→}
    44→
    45→impl MetadataKey {
    46→    /// Convert to string key for HashMap storage
    47→    pub fn as_str(&self) -> &str {
    48→        match self {
    49→            MetadataKey::Universe => "universe",
    50→            MetadataKey::SourceFile => "source_file",
    51→            MetadataKey::RpcName => "rpc_name",
    52→            MetadataKey::Extractor => "extractor",
    53→            MetadataKey::Inferred => "inferred",
    54→            MetadataKey::Variable => "variable",
    55→            MetadataKey::ImplCode => "impl_code",
    56→            MetadataKey::TestCode => "test_code",
    57→            MetadataKey::Pattern => "pattern",
    58→            MetadataKey::Value => "value",
    59→            MetadataKey::Min => "min",
    60→            MetadataKey::Max => "max",
    61→            MetadataKey::Source => "source",
    62→            MetadataKey::Custom(s) => s,
    63→        }
    64→    }
    65→
    66→    /// Parse from string
    67→    pub fn from_str(s: &str) -> Self {
    68→        match s {
    69→            "universe" => MetadataKey::Universe,
    70→            "source_file" => MetadataKey::SourceFile,
    71→            "rpc_name" => MetadataKey::RpcName,
    72→            "extractor" => MetadataKey::Extractor,
    73→            "inferred" => MetadataKey::Inferred,
    74→            "variable" => MetadataKey::Variable,
    75→            "impl_code" => MetadataKey::ImplCode,
    76→            "test_code" => MetadataKey::TestCode,
    77→            "pattern" => MetadataKey::Pattern,
    78→            "value" => MetadataKey::Value,
    79→            "min" => MetadataKey::Min,
    80→            "max" => MetadataKey::Max,
    81→            "source" => MetadataKey::Source,
    82→            other => MetadataKey::Custom(other.to_string()),
    83→        }
    84→    }
    85→}
