   125→impl Serialize for SpecSet {
   126→    fn serialize<S>(&self, serializer: S) -> Result<S::Ok, S::Error>
   127→    where
   128→        S: Serializer,
   129→    {
   130→        self.inner.serialize(serializer)
   131→    }
   132→}
