    96→#[derive(Debug, Clone, Serialize, Deserialize)]
    97→pub struct SpecGraph {
    98→    graph: DiGraph<SpecNodeData, SpecEdgeData>,
    99→    #[serde(skip)]
   100→    id_to_index: HashMap<String, NodeIndex>,
   101→    #[serde(skip)]
   102→    edge_id_to_index: HashMap<String, EdgeIndex>,
   103→}
   104→
   105→impl Default for SpecGraph {
   106→    fn default() -> Self {
   107→        Self::new()
   108→    }
   109→}
   110→
   111→impl SpecGraph {
   112→    pub fn new() -> Self {
   113→        Self {
   114→            graph: DiGraph::new(),
   115→            id_to_index: HashMap::new(),
   116→            edge_id_to_index: HashMap::new(),
   117→        }
   118→    }
   119→
   120→    /// Rebuild lookup indices after deserialization.
   121→    pub fn rebuild_indices(&mut self) {
   122→        self.id_to_index.clear();
   123→        self.edge_id_to_index.clear();
   124→        for idx in self.graph.node_indices() {
   125→            let node = &self.graph[idx];
   126→            self.id_to_index.insert(node.id.clone(), idx);
   127→        }
   128→        for idx in self.graph.edge_indices() {
   129→            let edge = &self.graph[idx];
   130→            self.edge_id_to_index.insert(edge.id.clone(), idx);
   131→        }
   132→    }
   133→
   134→    pub fn add_node(
   135→        &mut self,
   136→        content: String,
   137→        kind: NodeKind,
   138→        metadata: HashMap<String, String>,
   139→    ) -> &SpecNodeData {
   140→        let id = Uuid::new_v4().to_string();
   141→        let now = Utc::now().timestamp();
   142→        let data = SpecNodeData {
   143→            id: id.clone(),
   144→            content,
   145→            kind,
   146→            metadata,
   147→            created_at: now,
   148→            modified_at: now,
   149→            formality_layer: 0,  // Default to natural language
   150→        };
   151→        let idx = self.graph.add_node(data);
   152→        self.id_to_index.insert(id, idx);
   153→        &self.graph[idx]
   154→    }
   155→
   156→    /// Add a node from loaded data (preserves existing ID and timestamps)
   157→    pub fn add_node_from_loaded(&mut self, node: SpecNodeData) -> String {
   158→        let id = node.id.clone();
   159→        let idx = self.graph.add_node(node);
   160→        self.id_to_index.insert(id.clone(), idx);
   161→        id
   162→    }
   163→
   164→    pub fn get_node(&self, id: &str) -> Option<&SpecNodeData> {
   165→        self.id_to_index.get(id).map(|&idx| &self.graph[idx])
   166→    }
   167→
   168→    /// Find a node by content and kind (for deduplication)
   169→    pub fn find_node_by_content(&self, content: &str, kind: NodeKind) -> Option<&SpecNodeData> {
   170→        self.graph
   171→            .node_weights()
   172→            .find(|n| n.content == content && n.kind == kind)
   173→    }
   174→
   175→    pub fn update_node_formality(&mut self, id: &str, formality_layer: u8) -> bool {
   176→        if let Some(&idx) = self.id_to_index.get(id) {
   177→            if let Some(node) = self.graph.node_weight_mut(idx) {
   178→                node.formality_layer = formality_layer;
   179→                node.modified_at = Utc::now().timestamp();
   180→                return true;
   181→            }
   182→        }
   183→        false
   184→    }
   185→
   186→    pub fn update_node_metadata(&mut self, id: &str, key: String, value: String) -> Option<SpecNodeData> {
   187→        if let Some(&idx) = self.id_to_index.get(id) {
   188→            if let Some(node) = self.graph.node_weight_mut(idx) {
   189→                node.metadata.insert(key, value);
   190→                node.modified_at = Utc::now().timestamp();
   191→                return Some(node.clone());
   192→            }
   193→        }
   194→        None
   195→    }
   196→
   197→    pub fn remove_node(&mut self, id: &str) -> Option<SpecNodeData> {
   198→        if let Some(&idx) = self.id_to_index.get(id) {
   199→            // Remove related edge index entries
   200→            let edge_indices: Vec<EdgeIndex> = self
   201→                .graph
   202→                .edges_directed(idx, Direction::Outgoing)
   203→                .chain(self.graph.edges_directed(idx, Direction::Incoming))
   204→                .map(|e| e.id())
   205→                .collect();
   206→            for eidx in edge_indices {
   207→                if let Some(edge_data) = self.graph.edge_weight(eidx) {
   208→                    self.edge_id_to_index.remove(&edge_data.id);
   209→                }
   210→            }
   211→
   212→            let data = self.graph.remove_node(idx)?;
   213→            self.id_to_index.remove(&data.id);
   214→
   215→            // After removal petgraph may swap indices; rebuild to stay consistent.
   216→            self.rebuild_indices();
   217→            Some(data)
   218→        } else {
   219→            None
   220→        }
   221→    }
   222→
   223→    pub fn list_nodes(&self, kind_filter: Option<NodeKind>) -> Vec<&SpecNodeData> {
   224→        self.graph
   225→            .node_weights()
   226→            .filter(|n| kind_filter.is_none() || Some(n.kind) == kind_filter)
   227→            .collect()
   228→    }
   229→
   230→    pub fn add_edge(
   231→        &mut self,
   232→        source_id: &str,
   233→        target_id: &str,
   234→        kind: EdgeKind,
   235→        metadata: HashMap<String, String>,
   236→    ) -> Result<&SpecEdgeData, GraphError> {
   237→        let &src_idx = self
   238→            .id_to_index
   239→            .get(source_id)
   240→            .ok_or_else(|| GraphError::NodeNotFound(source_id.to_string()))?;
   241→        let &tgt_idx = self
   242→            .id_to_index
   243→            .get(target_id)
   244→            .ok_or_else(|| GraphError::NodeNotFound(target_id.to_string()))?;
   245→
   246→        let id = Uuid::new_v4().to_string();
   247→        let now = Utc::now().timestamp();
   248→        let data = SpecEdgeData {
   249→            id: id.clone(),
   250→            kind,
   251→            metadata,
   252→            created_at: now,
   253→        };
   254→        let eidx = self.graph.add_edge(src_idx, tgt_idx, data);
   255→        self.edge_id_to_index.insert(id, eidx);
   256→        Ok(&self.graph[eidx])
   257→    }
   258→
   259→    /// Add an edge from loaded data (preserves existing ID and timestamps)
   260→    pub fn add_edge_from_loaded(&mut self, edge: Edge) -> Result<String, GraphError> {
   261→        let &src_idx = self
   262→            .id_to_index
   263→            .get(&edge.source)
   264→            .ok_or_else(|| GraphError::NodeNotFound(edge.source.clone()))?;
   265→        let &tgt_idx = self
   266→            .id_to_index
   267→            .get(&edge.target)
   268→            .ok_or_else(|| GraphError::NodeNotFound(edge.target.clone()))?;
   269→
   270→        let id = edge.data.id.clone();
   271→        let eidx = self.graph.add_edge(src_idx, tgt_idx, edge.data);
   272→        self.edge_id_to_index.insert(id.clone(), eidx);
   273→        Ok(id)
   274→    }
   275→
   276→    pub fn remove_edge(&mut self, id: &str) -> Option<SpecEdgeData> {
   277→        if let Some(&eidx) = self.edge_id_to_index.get(id) {
   278→            let data = self.graph.remove_edge(eidx)?;
   279→            self.edge_id_to_index.remove(&data.id);
   280→            // Edge removal can invalidate other edge indices; rebuild.
   281→            self.rebuild_indices();
   282→            Some(data)
   283→        } else {
   284→            None
   285→        }
   286→    }
   287→
   288→    pub fn list_edges(&self, node_id: Option<&str>) -> Vec<(&SpecEdgeData, &str, &str)> {
   289→        self.graph
   290→            .edge_indices()
   291→            .filter_map(|eidx| {
   292→                let (src_idx, tgt_idx) = self.graph.edge_endpoints(eidx)?;
   293→                let edge_data = &self.graph[eidx];
   294→                let src_data = &self.graph[src_idx];
   295→                let tgt_data = &self.graph[tgt_idx];
   296→                if let Some(nid) = node_id {
   297→                    if src_data.id != nid && tgt_data.id != nid {
   298→                        return None;
   299→                    }
   300→                }

