    16→/// Z3-based SMT solver backend
    17→pub struct Z3Backend {
    18→    #[cfg(feature = "z3-solver")]
    19→    context: Context,
    20→}
    21→
    22→impl Z3Backend {
    23→    pub fn new() -> Self {
    24→        #[cfg(feature = "z3-solver")]
    25→        {
    26→            let config = Config::new();
    27→            let context = Context::new(&config);
    28→            Self { context }
    29→        }
    30→
    31→        #[cfg(not(feature = "z3-solver"))]
    32→        {
    33→            Self {}
    34→        }
    35→    }
    36→
    37→    /// Check satisfiability of constraints using Z3
    38→    ///
    39→    /// Returns (ProofStatus, ProofSteps)
    40→    pub fn check_satisfiability(
    41→        &self,
    42→        constraints: &[Constraint],
    43→    ) -> (ProofStatus, Vec<ProofStep>) {
    44→        #[cfg(feature = "z3-solver")]
    45→        {
    46→            self.check_satisfiability_z3(constraints)
    47→        }
    48→
    49→        #[cfg(not(feature = "z3-solver"))]
    50→        {
    51→            let mut steps = vec![ProofStep {
    52→                description: "Z3 solver not available (feature disabled)".to_string(),
    53→                justification: "Fallback to heuristic".to_string(),
    54→            }];
    55→            (ProofStatus::Unknown, steps)
    56→        }
    57→    }
    58→
    59→    /// Check consistency between two constraint sets using Z3
    60→    ///
    61→    /// Returns (ProofStatus, ProofSteps)
    62→    pub fn check_consistency(
    63→        &self,
    64→        constraints_a: &[Constraint],
    65→        constraints_b: &[Constraint],
    66→    ) -> (ProofStatus, Vec<ProofStep>) {
    67→        #[cfg(feature = "z3-solver")]
    68→        {
    69→            self.check_consistency_z3(constraints_a, constraints_b)
    70→        }
    71→
    72→        #[cfg(not(feature = "z3-solver"))]
    73→        {
    74→            let steps = vec![ProofStep {
    75→                description: "Z3 solver not available (feature disabled)".to_string(),
    76→                justification: "Fallback to heuristic".to_string(),
    77→            }];
    78→            (ProofStatus::Unknown, steps)
    79→        }
    80→    }
    81→
    82→    #[cfg(feature = "z3-solver")]
    83→    fn check_satisfiability_z3(
    84→        &self,
    85→        constraints: &[Constraint],
    86→    ) -> (ProofStatus, Vec<ProofStep>) {
    87→        let mut steps = Vec::new();
    88→
    89→        if constraints.is_empty() {
    90→            steps.push(ProofStep {
    91→                description: "No constraints - trivially satisfiable".to_string(),
    92→                justification: "Empty constraint set".to_string(),
    93→            });
    94→            return (ProofStatus::Proven, steps);
    95→        }
    96→
    97→        steps.push(ProofStep {
    98→            description: format!("Encoding {} constraints into Z3", constraints.len()),
    99→            justification: "SMT encoding".to_string(),
   100→        });
   101→
   102→        let solver = Solver::new(&self.context);
   103→        let mut var_map: HashMap<String, Int<'_>> = HashMap::new();
   104→
   105→        // Encode constraints into Z3
   106→        for constraint in constraints {
   107→            if let Some(assertion) = self.encode_constraint(&constraint.description, &mut var_map) {
   108→                solver.assert(&assertion);
   109→                steps.push(ProofStep {
   110→                    description: format!("Encoded: {}", constraint.description),
   111→                    justification: "Constraint encoding".to_string(),
   112→                });
   113→            }
   114→        }
   115→
   116→        steps.push(ProofStep {
   117→            description: "Invoking Z3 solver".to_string(),
   118→            justification: "SMT solving".to_string(),
   119→        });
   120→
   121→        // Check satisfiability
   122→        match solver.check() {
   123→            z3::SatResult::Sat => {
   124→                steps.push(ProofStep {
   125→                    description: "Z3 proved: SATISFIABLE (model exists)".to_string(),
   126→                    justification: "SMT solver verdict".to_string(),
   127→                });
   128→
   129→                // Get model for witness
   130→                if let Some(model) = solver.get_model() {
   131→                    let witness = format!("Witness: {}", model);
   132→                    steps.push(ProofStep {
   133→                        description: witness,
   134→                        justification: "Model extraction".to_string(),
   135→                    });
   136→                }
   137→
   138→                (ProofStatus::Proven, steps)
   139→            }
   140→            z3::SatResult::Unsat => {
   141→                steps.push(ProofStep {
   142→                    description: "Z3 proved: UNSATISFIABLE (no solution exists)".to_string(),
   143→                    justification: "SMT solver verdict".to_string(),
   144→                });
   145→
   146→                // Get unsat core for explanation
   147→                let core = solver.get_unsat_core();
   148→                if !core.is_empty() {
   149→                    let core_desc = format!("Unsat core: {} constraints conflict", core.len());
   150→                    steps.push(ProofStep {
   151→                        description: core_desc,
   152→                        justification: "Unsat core extraction".to_string(),
   153→                    });
   154→                }
   155→
   156→                (ProofStatus::Refuted, steps)
   157→            }
   158→            z3::SatResult::Unknown => {
   159→                steps.push(ProofStep {
   160→                    description: "Z3 returned: UNKNOWN (timeout or incomplete)".to_string(),
   161→                    justification: "SMT solver limitation".to_string(),
   162→                });
   163→                (ProofStatus::Unknown, steps)
   164→            }
   165→        }
   166→    }
   167→
   168→    #[cfg(feature = "z3-solver")]
   169→    fn check_consistency_z3(
   170→        &self,
   171→        constraints_a: &[Constraint],
   172→        constraints_b: &[Constraint],
   173→    ) -> (ProofStatus, Vec<ProofStep>) {
   174→        let mut steps = Vec::new();
   175→
   176→        steps.push(ProofStep {
