     1→/// Type-safe metadata system for UDAF model
     2→///
     3→/// This module provides strongly-typed metadata handling to prevent typos in metadata keys
     4→/// and provide convenient accessors for common metadata fields.
     5→
     6→use serde::{Deserialize, Serialize};
     7→use std::collections::HashMap;
