    99→/// Generic metadata container
   100→///
   101→/// Internally stores HashMap<String, String> for serialization compatibility,
   102→/// but provides type-safe access through MetadataKey.
   103→#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
   104→pub struct Metadata {
   105→    #[serde(flatten)]
   106→    inner: HashMap<String, String>,
   107→}
   108→
   109→impl Metadata {
   110→    /// Create empty metadata
   111→    pub fn new() -> Self {
   112→        Self {
   113→            inner: HashMap::new(),
   114→        }
   115→    }
   116→
   117→    /// Get value by metadata key
   118→    pub fn get(&self, key: &MetadataKey) -> Option<&String> {
   119→        self.inner.get(key.as_str())
   120→    }
   121→
   122→    /// Get value by string key (for compatibility)
   123→    pub fn get_str(&self, key: &str) -> Option<&String> {
   124→        self.inner.get(key)
   125→    }
   126→
   127→    /// Insert value with metadata key
   128→    pub fn insert(&mut self, key: MetadataKey, value: String) -> Option<String> {
   129→        self.inner.insert(key.as_str().to_string(), value)
   130→    }
   131→
   132→    /// Insert value with string key (for compatibility)
   133→    pub fn insert_str(&mut self, key: String, value: String) -> Option<String> {
   134→        self.inner.insert(key, value)
   135→    }
   136→
   137→    /// Remove value by metadata key
   138→    pub fn remove(&mut self, key: &MetadataKey) -> Option<String> {
   139→        self.inner.remove(key.as_str())
   140→    }
   141→
   142→    /// Check if key exists
   143→    pub fn contains_key(&self, key: &MetadataKey) -> bool {
   144→        self.inner.contains_key(key.as_str())
   145→    }
   146→
   147→    /// Get the inner HashMap (for direct access when needed)
   148→    pub fn inner(&self) -> &HashMap<String, String> {
   149→        &self.inner
   150→    }
   151→
   152→    /// Get mutable reference to inner HashMap
   153→    pub fn inner_mut(&mut self) -> &mut HashMap<String, String> {
   154→        &mut self.inner
   155→    }
   156→}
   157→
   158→impl Default for Metadata {
   159→    fn default() -> Self {
   160→        Self::new()
   161→    }
   162→}
   163→
   164→impl From<HashMap<String, String>> for Metadata {
   165→    fn from(map: HashMap<String, String>) -> Self {
   166→        Self { inner: map }
   167→    }
   168→}
   169→
   170→impl From<Metadata> for HashMap<String, String> {
   171→    fn from(metadata: Metadata) -> Self {
   172→        metadata.inner
   173→    }
   174→}
