   335→    /// Detect obvious contradictions between constraint sets
   336→    fn detect_obvious_contradiction(
   337→        &self,
   338→        constraints_a: &[crate::udaf::Constraint],
   339→        constraints_b: &[crate::udaf::Constraint],
   340→    ) -> bool {
   341→        // Check for explicit conflicts in numeric constraints
   342→        // e.g., "x >= 10" vs "x <= 5"
   343→
   344→        for a in constraints_a {
   345→            for b in constraints_b {
   346→                if self.constraints_conflict(&a.description, &b.description) {
   347→                    return true;
   348→                }
   349→            }
   350→        }
   351→
   352→        false
   353→    }
   354→
   355→    /// Detect obvious unsatisfiability within a constraint set
   356→    fn detect_obvious_unsatisfiability(
   357→        &self,
   358→        constraints: &[crate::udaf::Constraint],
   359→    ) -> bool {
   360→        // Check for internal conflicts
   361→        // e.g., "x >= 10" and "x <= 5" in the same spec
   362→
   363→        for i in 0..constraints.len() {
   364→            for j in (i+1)..constraints.len() {
   365→                if self.constraints_conflict(&constraints[i].description, &constraints[j].description) {
   366→                    return true;
   367→                }
   368→            }
   369→        }
   370→
   371→        false
   372→    }
   373→
   374→    /// Heuristic check if two constraints conflict
   375→    fn constraints_conflict(&self, desc_a: &str, desc_b: &str) -> bool {
   376→        let a_lower = desc_a.to_lowercase();
   377→        let b_lower = desc_b.to_lowercase();
   378→
   379→        // Numeric conflict patterns
   380→        // "at least X" vs "at most Y" where X > Y
   381→        if let (Some(min_a), Some(max_b)) = (
   382→            self.extract_minimum(&a_lower),
   383→            self.extract_maximum(&b_lower),
   384→        ) {
   385→            if min_a > max_b {
   386→                return true;
   387→            }
   388→        }
   389→
   390→        if let (Some(max_a), Some(min_b)) = (
   391→            self.extract_maximum(&a_lower),
   392→            self.extract_minimum(&b_lower),
   393→        ) {
   394→            if max_a < min_b {
   395→                return true;
   396→            }
   397→        }
   398→
   399→        // Boolean conflict patterns
   400→        // "must be X" vs "must not be X" / "forbidden X"
   401→        if (a_lower.contains("must be") || a_lower.contains("required"))
   402→            && (b_lower.contains("must not") || b_lower.contains("forbidden") || b_lower.contains("prohibited"))
   403→        {
   404→            // Check if they're about the same thing
   405→            let a_words: Vec<&str> = a_lower.split_whitespace().collect();
   406→            let b_words: Vec<&str> = b_lower.split_whitespace().collect();
   407→            let common_words: Vec<&str> = a_words.iter().filter(|w| b_words.contains(w)).copied().collect();
   408→
   409→            if common_words.len() >= 2 {
   410→                return true;
   411→            }
   412→        }
   413→
   414→        false
   415→    }
   416→
   417→    /// Extract minimum value from constraint description
   418→    fn extract_minimum(&self, desc: &str) -> Option<i64> {
   419→        // "at least N", "minimum N", ">= N"
   420→        if let Some(pos) = desc.find("at least") {
   421→            return self.extract_number(&desc[pos..]);
   422→        }
   423→        if let Some(pos) = desc.find("minimum") {
   424→            return self.extract_number(&desc[pos..]);
   425→        }
   426→        if let Some(pos) = desc.find(">=") {
   427→            return self.extract_number(&desc[pos..]);
   428→        }
   429→        None
   430→    }
   431→
   432→    /// Extract maximum value from constraint description
   433→    fn extract_maximum(&self, desc: &str) -> Option<i64> {
   434→        // "at most N", "maximum N", "<= N"
   435→        if let Some(pos) = desc.find("at most") {
   436→            return self.extract_number(&desc[pos..]);
   437→        }
   438→        if let Some(pos) = desc.find("maximum") {
   439→            return self.extract_number(&desc[pos..]);
   440→        }
   441→        if let Some(pos) = desc.find("<=") {
   442→            return self.extract_number(&desc[pos..]);
   443→        }
   444→        None
   445→    }
   446→
   447→    /// Extract first number from string
   448→    fn extract_number(&self, s: &str) -> Option<i64> {
   449→        for word in s.split_whitespace() {
   450→            if let Ok(n) = word.trim_matches(|c: char| !c.is_numeric()).parse::<i64>() {
   451→                return Some(n);
   452→            }
   453→        }
   454→        None
   455→    }
